                "• X საუკუნეში ბურგუნდიაში, კლუნის მონასტერში (დაარსდა 910 წელს), დაიწყო მოძრაობა, რომელიც XI საუკუნეში გაძლიერდა. მისი მიზანი ეკლესიის საერო ხელისუფლებისგან გათავისუფლება და ავტორიტეტის აღდგენა იყო. მთავარი მოთხოვნა ინვესტიტურის უფლების პაპისთვის გადაცემა გახლდათ.\n• 1073 წელს პაპი გახდა კლუნიელთა აღზრდილი, ძლიერი და განათლებული გრიგოლ VII (1073–1085). მისი აზრით, პაპი, მთავარეპისკოპოსები და ეპისკოპოსები მხოლოდ ეკლესიას უნდა დაენიშნა.",
