                "1075 წელს გრიგოლ VII-ემ თავისი შეხედულებები „პაპის დიქტატში“ (Dictatus Papae) ჩამოაყალიბა. მისი ძირითადი დებულებები:\n• რომის ეკლესია მხოლოდ ღმერთმა შექმნა;\n• მხოლოდ პაპი იწოდება მსოფლიო ეპისკოპოსად;\n• მხოლოდ პაპს შეუძლია ეპისკოპოსების დანიშვნა და გადაყენება;\n• მხოლოდ პაპს შეუძლია საიმპერატორო ნიშნების ტარება და იმპერატორების გადაყენება;\n• პაპის განსჯის უფლება არავის აქვს;\n• მთავრებმა მხოლოდ პაპს უნდა ეამბორონ ფეხზე;\n• პაპის გადაწყვეტილებას ვერავინ შეცვლის, პაპს კი ნებისმიერისას შეცვლა შეუძლია;\n• რომის ეკლესია არასდროს შემცდარა და არც შეცდება;\n• ვინც რომის ეკლესიას არ ეთანხმება, კათოლიკედ არ ითვლება;\n• პაპს შეუძლია ქვეშევრდომები უსამართლო მმართველისადმი ერთგულების ფიცისგან გაათავისუფლოს.",
