                "• XIII საუკუნის სომეხი ისტორიკოსი სტეფანოს ორბელიანი წერს: სიკვდილის წინ დავით V-მ დიდებულებსა და ძმას, გიორგის, სთხოვა, მისი ვაჟი გაეზარდათ და, როცა სრულწლოვანი გახდებოდა, მეფედ დაესვათ. ყრმა უფლისწული ივანე ორბელს ჩააბარეს და დიდებულებმა ფიცი დადეს, რომ ტახტს მას გადასცემდნენ.\n• „ქართლის ცხოვრებაში“ თამარ მეფის ისტორიკოსი ამბავს სხვაგვარად ჰყვება: გაზრდილი დემეტრე მამამისის მსგავსად მოიქცა — მომხრეებთან ერთად კანონიერ მეფეს განუდგა და დიდი ომი გააჩაღა, ღმერთმა კი გამარჯვება გიორგის მისცა.\n• სტეფანოს ორბელიანი ორბელთა საგვარეულოს წევრი იყო, თამარის ისტორიკოსი კი სამეფო კარს ემსახურებოდა. ისტორიკოსს ყოველთვის უნდა ჰკითხო: ვისი მხრიდან უყურებს ის მოვლენებს?",
