                "• ესპანელებმა არაბების წინააღმდეგ ბრძოლა და საკუთარი მიწების გათავისუფლება დაიწყეს — ამ პროცესს ისტორიაში რეკონკისტა ჰქვია. პირენეის ნახევარკუნძულის გათავისუფლებულ მიწებზე ესპანური სამეფოები ჩამოყალიბდა. ისინი წოდებრივ-წარმომადგენლობითი მონარქიები იყო.\n• XII საუკუნეში ერთ-ერთ ესპანურ სამეფოში — კასტილიაში — მეფის კარზე საბჭოში დიდი მიწათმფლობელები და უმაღლესი სასულიერო პირები იკრიბებოდნენ. შემდეგ სათათბიროდ ქალაქების წარმომადგენლებსაც იწვევდნენ.\n• ასე ჩამოყალიბდა ესპანურ სამეფოებში წოდებრივ-წარმომადგენლობითი ორგანო — კორტესი (სიტყვა „კორტედან“ — „სამეფო კარი“). კასტილიის კორტესი სამი პალატისგან შედგებოდა.\n• კასტილიის კორტესი ევროპაში პირველი იყო, რომელშიც თავისუფალი ქალაქებიც მონაწილეობდნენ.",
