                "• დღევანდელ მონღოლეთსა და მის მიმდებარე ტერიტორიებზე, ცენტრალური აზიის სტეპებში, მრავალი მონღოლური ტომი მომთაბარეობდა.\n• მათი ძირითადი საქმიანობა ნადირობა და მომთაბარე მესაქონლეობა იყო. ყოველ ტომს თავისი საძოვრები ჰქონდა — საზაფხულო და საზამთრო.\n• მონღოლები თექით დაფარულ კარვებში — იურტებში — ცხოვრობდნენ: იურტა ადვილად იშლებოდა და ერთი ადგილიდან მეორეზე გადაჰქონდათ. მომთაბარე ცხოვრებაში განსაკუთრებული ადგილი ცხენს ეკავა.\n• მკაცრი ცხოვრება მონღოლებს ფიზიკურად ძლიერსა და საბრძოლოდ მზადმყოფს ხდიდა: ბავშვები სამი წლის ასაკიდან სწავლობდნენ ცხენზე ჯდომას და მშვილდ-ისრის ხმარებას.\n• ტომებში წარჩინებულთა ფენა არსებობდა — ტომის უხუცესები, ყაენები (იგივე ხანები) და ნოინები. მათ საუკეთესო საძოვრები და დიდი ჯოგები ჰქონდათ. ტომები ხშირად ომობდნენ ერთმანეთში საძოვრების, წყლისა და ნადავლის გამო.",
