                "• ცენტრალური აზიისა და სპარსეთის დაპყრობის შემდეგ მონღოლთა ჯარი კავკასიისკენ დაიძრა და 1235 წელს საქართველოში მეორედ გამოჩნდა.\n• ჟამთააღმწერლის ცნობით, რუსუდანი ქუთაისში გადავიდა, თბილისის ციხისთავს, მუხასძეს, კი უბრძანა: თუ თათრები მოვიდნენ, ქალაქი, სასახლე და ისანი გადაწვი. მუხასძემ ქალაქი მტრის მოახლოებისთანავე გადაწვა, თუმცა მტერი ჯერ შორს იყო.\n• მონღოლი ნოინები ქართლში, თრიალეთში, სომხითში, ჯავახეთში, სამცხეში, ტაოში და სხვა მხარეებში გაიშალნენ. ქვეყანას მმართველი აღარ ჰყავდა. დიდებულები ციხეებში ჩაიკეტნენ: ამირსპასალარი ავაგი კაენის ციხეში ჩაიკეტა, მანდატურთუხუცესმა შანშემ აჭარას შეაფარა თავი, ვაჰრამ გაგელმა კი ქუთაისს მიაშურა.\n• ერთიანი წინააღმდეგობა ვერ შედგა: ჯერ ავაგი წავიდა მონღოლთა მმართველებთან და ზავი ითხოვა; მისი დახმარებით შანშე, ვაჰრამ გაგელი და სხვა დიდებულებიც დაუზავდნენ მონღოლებს. მესხებმა ბოლომდე იბრძოლეს, ბოლოს კი ივანე ციხისჯვარელ-ჯაყელმაც მეფის ნებართვით დადო ზავი.\n• დასავლეთ საქართველოს დაპყრობა მონღოლებმა ვერ შეძლეს, მაგრამ 1242/1243 წლებში საქართველოს მეფე რუსუდანმა მონღოლებთან ზავი დადო: ქვეყანას ყოველწლიური ხარკი და სამხედრო ვალდებულება — ლაშქრით დახმარება — დაეკისრა; ტახტზე ასულ მეფეს მონღოლთა ყაენი უნდა დაემტკიცებინა. რუსუდანი 1245 წელს გარდაიცვალა.",
