          description: "ჯალალ ად-დინის ლაშქრობა, გარნისის ბრძოლა და თბილისის დაცემა (1226), რუსუდანის მიმოწერა რომის პაპებთან, მონღოლთა ბატონობის დამყარება და დუმნები",
