                "• დემეტრე მეფეს ხშირად უწევდა სიბაზე დგომა და მონღოლთა ლაშქრობებში მონაწილეობა.\n• XIII საუკუნის 60-იანი წლებიდან მონღოლები ეგვიპტეს უტევდნენ, მაგრამ უშედეგოდ. ეს საომარი კამპანია დიდხანს გაგრძელდა. 1280 წლის ბრძოლებში 30 000 ქართველი, სომეხი და ბერძენი ჯარისკაცი მონაწილეობდა. მომდევნო წელს თავად დემეტრე მეფეც 5000 ქართველი მეომრით იბრძოდა მონღოლების გვერდით. ლაშქრობები მონღოლთა მარცხით დასრულდა: ქართველ მეომართა უდიდესი ნაწილი დაიღუპა, დემეტრე კი სიკვდილს ძლივს გადაურჩა.\n• ამავე დროს, 1270 წლიდან, მიმდინარეობდა ჯვაროსანთა ბოლო, VIII ლაშქრობა, რომელსაც საფრანგეთის მეფე ლუი IX მეთაურობდა. არც ამ ლაშქრობას მოჰყოლია შედეგი.\n• დემეტრემ წერილი მიიღო რომის პაპ ნიკოლოზ IV-ისგან. პაპი წერდა: ჩვენ ვცდილობთ, წმინდა ადგილები ხელმეორედ დავიხსნათ, და ეს ყველა ქრისტიანი ხელმწიფის პირველი საზრუნავი უნდა იყოს. ამიტომ გთხოვთ, მონაწილეობა მიიღოთ ამ საქმეში, მოამზადოთ მთელი თქვენი სამეფო და სხვა კათოლიკე მეფეების დახმარებით ეს საქმე ბედნიერად დაასრულოთ.",
