                "• დემეტრე II ილხანთა ყაენის პირველ ვეზირთან, ბუღასთან, მეგობრობდა და ამით ქვეყნისთვის გარკვეულ შეღავათებს იღებდა. 1289 წელს ბუღა ნოინი შეთქმულების გამო სიკვდილით დასაჯეს, დემეტრე კი, როგორც ბუღას მეგობარი, ყაენთან დაიბარეს.\n• სამეფო კარზე გამართულ დარბაზზე მეფეს ურჩევდნენ, ყაენთან არ წასულიყო და მთიულეთისთვის შეეფარებინა თავი. ჟამთააღმწერლის ცნობით, დემეტრემ თქვა: თუ საყაენოში არ წავალ და მთიულეთის სიმაგრეებს შევაფარებ თავს, უამრავი ქრისტიანი დაიღუპება და ტყვედ ჩავარდება, მონღოლები კი ეკლესიებს დაარბევენ; ამიტომ ყაენთან წავალ და ჩემი ერისთვის თავს გავწირავ — თუ მომკლავენ, ჩემი ქვეყანა უვნებლად გადარჩება.\n• დემეტრე შვილთან ერთად საყაენოში წავიდა და ერთგულების დასამტკიცებლად ძღვენიც წაიღო, მაგრამ ჩასვლისთანავე დააპატიმრეს. მისი ქონება აღწერეს, თბილისში მოხელე გაგზავნეს და ყველაფერი ჩამოართვეს.\n• მონღოლური წესით ქონების ჩამორთმევას სიკვდილით დასჯა უნდა მოჰყოლოდა, მაგრამ ყაენი ყოყმანობდა: საქართველოში მეფობის სხვა კანდიდატი არ ჰყავდა. მაშინ სადუნის ვაჟმა, ხუტლუ ბუღამ, ყაენს დავით ნარინის ვაჟი, ვახტანგი, შესთავაზა — მისი გამეფებით მონღოლებს ორივე სამეფო დაემორჩილებოდა.\n• ყაენმა დემეტრე სიკვდილით დასაჯა: 1289 წლის 12 მარტს, შაბათ დღეს, მას თავი მოჰკვეთეს. ამ თავგანწირვის გამო ხალხმა დემეტრეს „თავდადებული“ უწოდა.",
