                "• იერუსალიმსა და პალესტინაში ქართველებს არაერთი მონასტერი ეკუთვნოდათ და ქართული სახელმწიფო მუდამ ზრუნავდა მათ შენარჩუნებაზე. წმინდა მიწაზე საკუთარი მონასტრები სხვა ქრისტიან ხალხებსაც ჰქონდათ, რომლებთანაც ქართველ ბერებს სულიერი და საქმიანი ურთიერთობა აკავშირებდა.\n• XIII საუკუნის მეორე ნახევარში მამლუქებმა ქართველებს ჩამოართვეს ბაგრატ IV-ის დროს აშენებული ჯვრის მონასტერი: ეჭვობდნენ, რომ ქართველი ბერები მათ დაუძინებელ მტრებს — მონღოლებს — პალესტინის ამბებს აცნობდნენ.\n• მონასტრის დასაბრუნებლად XIV საუკუნის დასაწყისში აღმოსავლეთ და დასავლეთ საქართველოს მეფეები ზრუნავდნენ. დიდ წარმატებას მიაღწია ლიხთიმერეთის მეფემ, დავით ნარინის ძემ, კონსტანტინემ — მისი ძალისხმევით 1310 წელს მამლუქებმა ჯვრის მონასტერი ქართველებს დაუბრუნეს.",
