                "• 1400 წელს თემურმა გიორგი VII-ს მისწერა: მე შენი მეფე ვარ, მოდი ჩემთან, შემომირიგდი და პატივს გცემ; თუ არ დამემორჩილები, ლაშქარს ვუბრძანებ, შენი ქვეყანა ააოხროს. თემური თაჰერის გადაცემასაც ითხოვდა. გიორგიმ უპასუხა: მე შენზე ნაკლები მეფე არ ვარ და თუ მუქარას არ აღასრულებ, დიაცი იქნები.\n• იმავე წლის გაზაფხულზე თემური დიდი ჯარით დაიძრა. მარტო ქვემო ქართლში 15 ციხე აიღო, ბირთვისის ციხე კი ვერ აიღო. შემდეგ დედაქალაქი დაიკავა და მუხრანში დაბანაკდა, დაარბია ქსნის ხეობა და დაანგრია გორი. დიდი წინააღმდეგობა გაუწიეს ჟოვრეთის (ძამის) და სველნეთის ციხეების დამცველებმა.\n• შემდეგ თემურმა სამცხე ააოხრა, თეძმის ხეობაში რკონისა და ქვათახევის მონასტრები დაანგრია, მცხეთაში სვეტიცხოველი გაძარცვა. დაბრუნებისას ტაოში 7 ციხე აიღო, მათ შორის ფანასკერტი, და 60 ათასზე მეტი ტყვე წაიყვანა.",
