                "• ბირთვისის ციხე სამი მხრიდან ციცაბო კლდეებით იყო დაცული, ციხისკენ მიმავალ ერთადერთ ბილიკზე კი ასზე მეტი კაცი ვერ ეტეოდა. ამიტომ დიდი ჯარი ციხეს ვერ უტევდა, მეციხოვნეები კი იერიშებს ადვილად იგერიებდნენ.\n• 1403 წელს თემურმა ბირთვისის გარშემო სამი დროებითი ციხე ააგო და ყოველდღე უტევდა. მის ჯარში მთაში გამოცდილი მებრძოლებიც იყვნენ: ერთ-ერთი მათგანი ღამით ციცაბო კლდეზე აცოცდა და ციხეში ყოფნის დასამტკიცებლად იქიდან თხაც კი ჩამოიყვანა.\n• რამდენიმედღიანი განუწყვეტელი შეტევის შემდეგ გადაღლილ მეციხოვნეებს ღამით ჩაეძინათ. 52 მოხალისე კლდეზე ჩუმად აცოცდა, ჭიშკარი გააღო და თემურის ლაშქარი ციხეში შეიჭრა. დამცველთა უმეტესობა ბრძოლაში დაიღუპა, გადარჩენილები სიკვდილით დასაჯეს, მათი ოჯახები კი ტყვედ წაასხეს.\n• თემურმა საქართველო ბოლომდე მაინც ვერ დაიმორჩილა: გიორგი VII-მ მისი უზენაესობა მხოლოდ ფორმალურად აღიარა — დამპყრობელს პირადად არ ეახლა და მისი ზოგი მოთხოვნა არ შეასრულა. საქართველოში დიდი ზარალის შემდეგ თემური იძულებული გახდა, ამას დასჯერებოდა.",
