                "• ოსმალთა სულთანმა მეჰმედ II-მ კონსტანტინოპოლის აღება გადაწყვიტა და ომისთვის საგულდაგულოდ მოემზადა. ქალაქის აღებას თურქები მანამდეც ცდილობდნენ, მაგრამ ყოველ ჯერზე მარცხდებოდნენ.\n• მეჰმედის აზრით, მიზეზი ის იყო, რომ ალყაში მყოფ ჯარს ზღვიდან ფლოტი ვერ ეხმარებოდა. ზღვაზე ბიზანტიელები ბატონობდნენ: თავისუფლად ცურვის ნებას მხოლოდ ვენეციელებსა და გენუელებს აძლევდნენ, სანაპიროზე კი თურქებს ხშირად თავს ესხმოდნენ.\n• 1451–1452 წლებში მეჰმედმა ბოსფორის სრუტის ყველაზე ვიწრო ადგილას ციხესიმაგრე ააგო — მას კონსტანტინოპოლი შავი ზღვისთვის უნდა მოეწყვიტა. მშენებლობის მიზეზის გასარკვევად გაგზავნილი ბიზანტიელი ელჩები სულთანმა უპასუხოდ გააბრუნა, მეორე ელჩობას კი თავები მოჰკვეთეს. ეს ომის არაოფიციალურად გამოცხადებას ნიშნავდა.\n• ციხეს ბოღაზ-ქესენი (თურქულად — „ყელის გამომჭრელი“) უწოდეს. 1452 წელს დასრულებულ ციხეში ბომბარდები დადგეს, რომლებიც სრუტეში მცურავ ბიზანტიურ ხომალდებს ესროდნენ.",
