                "• იმპერიის შექმნისთანავე ოსმალებმა ქვეყნის მოწყობაზე იზრუნეს: დახვეწეს სახელმწიფო აპარატი, დაყვეს ტერიტორია და შემოიღეს საგადასახადო სისტემა.\n• იმპერია ოლქებად — ვილაიეთებად — და უფრო მცირე ერთეულებად დაიყო. მათ სხვადასხვა რანგის მოხელე-გამგებლები განაგებდნენ, რომელთა შორის უმაღლესი ფაშა იყო. იმპერიის კანონები მუსლიმურ სამართალს ეფუძნებოდა.\n• ევროპელებს განსაკუთრებით აოცებდა, რომ ქვეყნის უმაღლესი მოხელეები — სახელმწიფოს მართვაში სულთნის თანაშემწეები — მისი „ყურმოჭრილი მონები“ იყვნენ, თუმცა მუსლიმური სამართლით მუსლიმი მონა არ შეიძლებოდა ყოფილიყო.\n• რიგითი მოხელე ან ყოფილი იანიჩარი ვეზირი ან ფაშაც შეიძლებოდა გამხდარიყო, მაგრამ ყოველთვის უუფლებო და მორჩილ მსახურად რჩებოდა: მცირე დანაშაულისთვისაც კი სულთანს შეეძლო მისთვის თავი მოეკვეთა. სულთნის მსახურისთვის უდიდესი ჯილდო სულთნისგან ნაბოძები საპატიო ტანსაცმელი იყო.",
