                "• დიდი გეოგრაფიული აღმოჩენების შემდეგ ხმელთაშუა და შავმა ზღვებმა ევროპული ვაჭრობისთვის მნიშვნელობა დაკარგეს, „აბრეშუმის გზამ“ კი, ფაქტობრივად, ფუნქცია დაკარგა.\n• აღმოჩენებმა დასავლეთ ევროპის სახელმწიფოთა ძალთა თანაფარდობა შეცვალა. ადრე მთავარი სავაჭრო ცენტრები იტალიური ქალაქები — ვენეცია და გენუა — იყო; ახალი გზების აღმოჩენის შემდეგ ჯერ ესპანეთი და პორტუგალია, შემდეგ კი ნიდერლანდები, ინგლისი და საფრანგეთი დაწინაურდნენ. ყველაზე მნიშვნელოვან სავაჭრო ცენტრად ანტვერპენი იქცა, სადაც პორტუგალიიდან და ესპანეთიდან შემოტანილი სანელებლები, ვერცხლი და ქსოვილები იყრიდა თავს.\n• ახალმა აღმოჩენებმა დიდი ბიძგი მისცა გეოგრაფიის, ეთნოგრაფიის, ბოტანიკისა და ზოოლოგიის განვითარებას; გაიზარდა ცოდნა ტექნიკაში, ეკონომიკასა და სამართალში. ახალ ხალხებთან გაცნობამ ევროპელთა აზროვნებაც შეცვალა. აღმოჩენების ეპოქა დაემთხვა აღორძინების ხანას — რენესანსს.",
